entries[79876] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort\nHeilt den Zaubernden um 1% seiner maximalen Gesundheit." }
entries[79877] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort\nGreift das Ziel sofort an und verursacht 120% Waffenschaden. Zudem stellen erfolgreiche Nahkampfangriffe 1% der maximalen Gesundheit wieder her. Der Effekt hält 10 Sek. lang an." }
entries[79878] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort an und verursacht 120% normalen Waffenschaden. Zudem stellen erfolgreiche Nahkampfangriffe 1% der maximalen Gesundheit wieder her. Der Effekt hält 10 Sek. lang an." }
entries[79879] = { ["name"] = "Elektrische Entladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt bis zu 3 Gegnern im Umkreis von 8 Metern 2559 Naturschaden zu." }
entries[79880] = { ["name"] = "Verlangsamen", ["text"] = "30 Meter Reichweite\nSofort\nErhöht die Zeit zwischen den Angriffen eines Gegners um 25%, verlangsamt sein Zaubertempo um 25% und seine Bewegungsgeschwindigkeit um 25%. Hält 6 Sek. lang an." }
entries[79881] = { ["name"] = "Zerschmettern", ["text"] = "Nahkampfreichweite\nWirken in 1.5 sek.\nZerschmettert den Gegner und verursacht Waffenschaden plus zusätzlichen Schaden." }
entries[79882] = { ["name"] = "Niederstoßen" }
entries[79883] = { ["name"] = "Zerschmetternder Wurf", ["text"] = "30 Meter ReichweiteWirken in 1.5 sek. 5 min Abklingzeit\nBenötigt Nahkampfwaffe\nWirft Eure Waffe nach dem Feind. Verursacht Waffenschaden verringert die Rüstung des Ziels 10 Sek. lang um 20%." }
entries[79884] = { ["name"] = "Blitzschlag", ["text"] = "15 Mana 40 Meter Reichweite\nWirken in 3 sek.\nDeckt einen Feind mit Blitzschlägen ein und fügt ihm Naturschaden zu." }
entries[79885] = { ["name"] = "Herzstoß", ["text"] = "1 Rune / -10 Runenmacht Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nSchlägt das Ziel und seinen nächsten Verbündeten sofort. Fügt dem Primärziel 110% Waffenschaden und dem Sekundärziel 55% Waffenschaden zu." }
entries[79886] = { ["name"] = "Lavaeruption", ["text"] = "10% von Grundmana 30 Meter Reichweite\nWirken in 3.5 sek.\nIhr schleudert flüssige Lava auf das Ziel, die Feuerschaden verursacht." }
entries[79887] = { ["name"] = "Tod und Verfall", ["text"] = "30 Meter Reichweite\nSofort\nFügt allen Zielen im betroffenen Gebiet 10 Sek. lang alle 1 Sek. Schattenschaden zu." }
entries[79888] = { ["name"] = "Blitzableiter", ["text"] = "45 Meter Reichweite\nSofort\nInfiziert einen Feind 15 Sek. lang, wodurch an allen in der Nähe befindlichen Verbündeten alle 2 Sek. Naturschaden verursacht wird." }
entries[79889] = { ["name"] = "Blitzableiter", ["text"] = "Sofort\nFügt nahen befreundeten Einheiten Naturschaden zu." }
entries[79890] = { ["name"] = "Flammenschock", ["text"] = "25 Mana 20 Meter Reichweite\nSofort\nVerbrennt sofort einen Feind und fügt ihm dann 12 Sek. lang alle 3 Sek. zusätzlichen Feuerschaden zu." }
entries[79891] = { ["name"] = "Horn des Winters", ["text"] = "Sofort\nDer Todesritter bläst das Horn des Winters und erhält 10 Runenmacht. Stärke und Beweglichkeit werden um 5 erhöht. Hält 2 Min. lang an." }
entries[79892] = { ["name"] = "Wasserschild", ["text"] = "Sofort\nDer Zaubernde wird von 3 Wasserkugeln umgeben. Gegen den Zaubernden gerichtete Angriffe oder Zauber verursachen Frostschaden und verlangsamen das Zaubertempo des Angreifers. 3 Aufladungen. Hält 10 Min. lang an.\n(4s Abklingzeit)" }
entries[79893] = { ["name"] = "Blutwurm", ["text"] = "30 Meter Reichweite\nSofort\nErschafft einen Blutwurm, der nahe Ziele angreift. Hält 8 Sek. lang an." }
entries[79894] = { ["name"] = "Todesgriff", ["text"] = "30 Meter Reichweite\nSofort 4 sek. Abklingzeit\nMacht sich die unheilige Energie, die alle Materie umgibt und verbindet, zunutze, um das Ziel zum Zaubernden hinzuziehen und es zu zwingen, ihn bis Abbruch lang anzugreifen." }
entries[79895] = { ["name"] = "Froststoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nSchlägt das Ziel sofort und verursacht 110% Waffenschaden als Frostschaden." }
entries[79896] = { ["name"] = "Heulende Böe", ["text"] = "20 Meter Reichweite\nWirken in 1.5 sek.\nWeht dem Ziel eine eisige Böe entgegen, die allen Zielen innerhalb von 10 Metern Frostschaden zufügt. Gefrorene Ziele erleiden dreifachen Schaden." }
entries[79897] = { ["name"] = "Eisige Berührung", ["text"] = "20 Meter Reichweite\nSofort\nVerursacht Frostschaden und verringert 8 Sek. lang das Nahkampf-, Distanzangriffs- und Zaubertempo des Ziels um 15%." }
entries[79898] = { ["name"] = "Corrupted Body (Self)" }
entries[79899] = { ["name"] = "Eisketten", ["text"] = "25 Meter Reichweite\nSofort 8 sek. Abklingzeit\nUmschlingt das Ziel mit eisigen Ketten und verringert seine Bewegungsgeschwindigkeit auf 5% des normalen Wertes. Das Ziel erhält im Verlauf von 10 Sek. pro Sekunde 10% seiner Bewegungsgeschwindigkeit zurück." }
entries[79900] = { ["name"] = "Instabiler Schild", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nAngriffe auf den instabilen Schild verursachen einen statischen Schock am Standort eines nahen Feindes. Der statische Schock fügt Feinden im Umkreis von 6 Metern um das Ziel 13121 Naturschaden zu.\n(250ms Abklingzeit)" }
entries[79901] = { ["name"] = "Blutseuche", ["text"] = "Nahkampfreichweite\nSofort\nEin bösartiger Schlag, der Waffenschaden verursacht, das Ziel verseucht und ihm so im Verlauf von 12 Sek. Schattenschaden zufügt." }
entries[79902] = { ["name"] = "Seuchenstoß", ["text"] = "Nahkampfreichweite\nSofort\nEin bösartiger Schlag, der Waffenschaden verursacht, das Ziel verseucht und im Verlauf von 12 Sek. 37 Schattenschaden verursacht." }
entries[79903] = { ["name"] = "Todesmantel", ["text"] = "45 Meter Reichweite\nWirken in 1.5 sek.\nFügt einem zufälligen nahen Ziel 147 Schattenschaden zu." }
entries[79904] = { ["name"] = "Ansturm", ["text"] = "45 Meter Reichweite\nSofort 3 sek. Abklingzeit\nStürmt auf einen Gegner zu, fügt ihm sowie seinen nahen Verbündeten 825 Schaden zu und stößt alle betroffenen Ziele zurück." }
entries[79905] = { ["name"] = "Totenerweckung", ["text"] = "30 Meter Reichweite\nSofort\nErweckt einen Ghul, der an Eurer Seite kämpft. Steht kein humanoider Leichnam zur Verfügung, der Erfahrung oder Ehre gewährt, wird Leichenstaub benötigt, um den Zauber zu wirken. Ihr könnt nur maximal einen Ghul gleichzeitig beschwören. Hält 1 Min. lang" }
entries[79907] = { ["name"] = "Antimagisches Feld", ["text"] = "1 Rune / -10 Runenmacht\nSofort\nPlatziert ein großes, ortsgebundenes, antimagisches Feld, das den erlittenen Zauberschaden aller darin befindlichen Gruppen- oder Schlachtzugsmitglieder um 49% verringert. Das antimagische Feld hält 6 Sek. lang an oder bis es (0 + 2 * Angriffskraft) Zauberschaden absorbiert hat." }
entries[79908] = { ["name"] = "Statischer Schock" }
entries[79909] = { ["name"] = "Geißelstoß", ["text"] = "1 Rune / -10 Runenmacht Nahkampfreichweite\nSofort\nEin unheiliger Stoß, der 150% Waffenschaden in Form von Schattenschaden verursacht." }
entries[79910] = { ["name"] = "Instabiler Schild" }
entries[79911] = { ["name"] = "Statischer Schock" }
entries[79912] = { ["name"] = "Statischer Schock", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt Gegnern im Umkreis von 6 Metern 226 Naturschaden zu." }
entries[79913] = { ["name"] = "Kettenblitzschlag", ["text"] = "30 Mana 30 Meter Reichweite\nWirken in 3 sek. 6 sek. Abklingzeit\nTrifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 3 Ziele aus und fügt jedem folgenden Ziel immer geringeren Naturschaden zu." }
entries[79914] = { ["name"] = "Wildgeist", ["text"] = "12% von Grundmana 30 Meter Reichweite\nSofort 8 sek. Abklingzeit\nBeschwört zwei Geisterwölfe, die unter dem Befehl des Schamanen stehen. Hält 45 Sek. lang an." }
entries[79919] = { ["name"] = "Trägt ein Samophlang", ["text"] = "Sofort\nHält sein Samophlang voller Stolz in die Höhe." }
entries[79920] = { ["name"] = "Shared Health" }
entries[79921] = { ["name"] = "Schattenflamme", ["text"] = "15 Meter Reichweite\nKanalisiert (Wirken in 3 sek.) 3 sek. Abklingzeit\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden 1422 Feuerschaden zu." }
entries[79922] = { ["name"] = "Schinden", ["text"] = "Wirken in 0.6 sek.\nFügt allen Feinden im Umkreis von 4 Metern alle 0,25 Sek. 60% Waffenschaden zu. Hält 5 Sek. lang an." }
entries[79923] = { ["name"] = "Schinden", ["text"] = "Sofort\nFügt allen Feinden im Umkreis von 4 Metern alle 0,25 Sek. 60% Waffenschaden zu. Hält 5 Sek. lang an." }
entries[79924] = { ["name"] = "Welle der Heilung", ["text"] = "35 Mana 40 Meter Reichweite\nWirken in 3 sek.\nRuft Naturmagie an, um einen Verbündeten zu heilen." }
entries[79925] = { ["name"] = "Frostschock", ["text"] = "25 Mana 20 Meter Reichweite\nSofort\nFügt einem Gegner Frostschaden zu und verringert 6 Sek. lang seine Bewegungsgeschwindigkeit." }
entries[79926] = { ["name"] = "Urtümlicher Schlag", ["text"] = "8% von Grundmana Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin sofortiger Waffenstoß, der 111 zusätzlichen Schaden verursacht." }
entries[79927] = { ["name"] = "Erdschild", ["text"] = "40 Meter Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild. Nahkampfangriffe heilen das geschützte Ziel, dieser Effekt tritt aber nur einmal alle paar Sekunden auf. 10 Aufladungen. Hält 10 Min. lang an.\n(3.5s Abklingzeit)" }
entries[79928] = { ["name"] = "Erdschild", ["text"] = "Sofort\nSchützt das Ziel mit einem Erdschild. Nahkampfangriffe heilen das geschützte Ziel, dieser Effekt tritt aber nur einmal alle paar Sekunden auf." }
entries[79929] = { ["name"] = "Blutfratzen suchen" }
entries[79930] = { ["name"] = "Verderbnis", ["text"] = "25 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerderbt Gegner in der Nähe und fügt ihnen 15 Sek. lang alle 3 Sek. Schattenschaden zu." }
entries[79931] = { ["name"] = "Defeat Crushcog Credit" }
entries[79932] = { ["name"] = "Schattenblitz", ["text"] = "15 Mana 40 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Feind und verursacht Schattenschaden." }
entries[79933] = { ["name"] = "Blutsauger", ["text"] = "30 Mana 20 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nEntzieht einem Gegner im Verlauf von 5 Sek. Gesundheit und überträgt sie auf den Zaubernden." }
entries[79934] = { ["name"] = "Dämonenrüstung", ["text"] = "31% von Grundmana\nSofort\nBeschützt den Zaubernden, verringert seinen erlittenen körperlichen Schaden und erhöht die Menge an wiederhergestellter Gesundheit durch Zauber und Effekte um 20%. Es kann immer nur ein Rüstungszauber gleichzeitig aktiv sein. Hält 30 Min. lang an." }
entries[79936] = { ["name"] = "Slam Smoot" }
entries[79937] = { ["name"] = "Feuerbrand", ["text"] = "30 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerbrennt sofort einen Feind und fügt ihm dann 15 Sek. lang alle 3 Sek. zusätzlichen Feuerschaden zu." }
entries[79938] = { ["name"] = "Verbrennen", ["text"] = "15 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nFügt Eurem Ziel Feuerschaden zu." }
entries[79939] = { ["name"] = "Chaosblitz", ["text"] = "35 Mana 40 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Blitz chaotischen Feuers auf den Gegner und verursacht Feuerschaden. Dem Chaosblitz kann nicht widerstanden werden und er durchbricht defensive Immunitäten." }
entries[79948] = { ["name"] = "Summon Samophlange" }
entries[79949] = { ["name"] = "Wasserschild", ["text"] = "Sofort\nDer Zaubernde wird von 0 Wasserkugeln umgeben, die alle 5 Sek. 2015 Mana gewähren. Trifft ein Zauber, ein Nahkampf- oder Distanzangriff den Zaubernden, erhält er 2 Mana und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 1 Stunde lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
entries[79950] = { ["name"] = "Wasserschild", ["text"] = "Sofort\nDer Zaubernde wird von 0 Wasserkugeln umgeben, die alle 5 Sek. 2015 Mana gewähren. Trifft ein Zauber, ein Nahkampf- oder Distanzangriff den Zaubernden, erhält er 2 Mana und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 1 Stunde lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein." }
entries[79952] = { ["name"] = "Be Raptor: Summon Raptor 1" }
entries[79953] = { ["name"] = "Be Raptor: Forcecast Teleport In (Master)" }
entries[79954] = { ["name"] = "Teufelsrüstung", ["text"] = "28% von Grundmana\nSofort\nUmgibt Euch mit Teufelsenergie, die Eure Zaubermacht um 10% erhöht. Zusätzlich regeneriert Ihr alle 5 Sek. 2% Eurer gesamten Gesundheit. Es kann immer nur eine Art Rüstungszauber gleichzeitig aktiv sein. Hält 30 Min. lang an." }
entries[79955] = { ["name"] = "Feuerregen", ["text"] = "35 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 9 sek.)\nLässt einen Feuerregen niedergehen, der alle Gegner im Zielgebiet verbrennt und ihnen 9 Sek. lang alle 3 Sek. Feuerschaden zufügt." }
entries[79956] = { ["name"] = "Fluch der Elemente", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel 30 Sek. lang und verringert so seinen Widerstand gegen Arkan-, Feuer-, Frost-, Natur- und Schattenschaden um 125, während der erlittene Magieschaden um 8% erhöht wird. Es kann immer nur jeweils ein Fluch pro Zauberndem auf einem beliebigen Ziel aktiv sein." }
entries[79957] = { ["name"] = "Seelenverbindung", ["text"] = "16% von Grundmana 100 Meter Reichweite\nSofort\nBei Aktivierung wird sämtlicher vom Zaubernden erlittene Schaden um 20% verringert und auf seinen Wichtel, Leerwandler, Sukkubus, Teufelsjäger, seine Teufelswache oder seinen versklavten Dämon übertragen. Dieser Schaden kann nicht verhindert werden. Hält an, solange der Dämon aktiv ist und kontrolliert wird." }
entries[79958] = { ["name"] = "Teufelswache beschwören", ["text"] = "80% von Grundmana\nSofort\nBeschwört eine Teufelswache unter dem Befehl des Zaubernden." }
entries[79960] = { ["name"] = "Heiliges Licht", ["text"] = "35 Mana 40 Meter Reichweite\nWirken in 3 sek.\nRuft heilige Magie an, um einen Verbündeten zu heilen." }
entries[79961] = { ["name"] = "Heiliger Schock", ["text"] = "25 Mana 30 Meter Reichweite\nSofort\nÜberzieht das Ziel mit heiliger Energie und fügt einem Gegner Heiligschaden zu." }
entries[79962] = { ["name"] = "Siegel der Rechtschaffenheit", ["text"] = "14% von Grundmana\nSofort\nErfüllt den Zaubernden 10 Min. lang mit heiligem Licht, durch das jeder Einzelziel-Nahkampfangriff zusätzlichen Heiligschaden verursacht." }
entries[79963] = { ["name"] = "Aura der Konzentration", ["text"] = "Sofort\nVerbündete im Umkreis von 40 Metern verlieren bei erlittenem Schaden 100% weniger Zauber- und Kanalisierungszeit." }
entries[79964] = { ["name"] = "Exorzismus", ["text"] = "30 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nFügt einem Gegner Heiligschaden zu." }
entries[79965] = { ["name"] = "Schild des Rächers", ["text"] = "30 Mana 30 Meter Reichweite\nWirken in 1 sek.\nSchleudert einen heiligen Schild auf den Gegner, der Heiligschaden zufügt, ihn benommen macht und dann auf weitere nahe Gegner überspringt. Wirkt auf insgesamt 2 Ziele." }
entries[79966] = { ["name"] = "Weihe", ["text"] = "22% von Grundmana\nSofort\nWeiht das Land unter dem Zaubernden und fügt Gegnern, die das Gebiet betreten, im Verlauf von 8 Sek. Heiligschaden zu." }
entries[79967] = { ["name"] = "Heiliger Schild", ["text"] = "10% von Grundmana\nSofort\nErhöht die Blockchance 10 Sek. lang um 30% und verursacht, während der Effekt aktiv ist, mit jedem Blocken Heiligschaden. Jedes Blocken zehrt eine Aufladung auf. 3 Aufladungen." }
entries[79968] = { ["name"] = "Segen der Könige", ["text"] = "30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen, welcher 5 Min. lang seine Stärke, Beweglichkeit, Ausdauer und Intelligenz um 5% erhöht." }
entries[79970] = { ["name"] = "Göttlicher Sturm", ["text"] = "20% von Grundmana Nahkampfreichweite\nSofort\nEin sofortiger Waffenangriff, der bis zu 4 Gegnern innerhalb von 8 Metern Heiligschaden zufügt." }
entries[79971] = { ["name"] = "Hammer des Zorns", ["text"] = "30 Mana 40 Meter Reichweite\nWirken in 2 sek.\nSchleudert einen Hammer, der einem Gegner Heiligschaden zufügt." }
entries[79972] = { ["name"] = "Siegel der Wahrheit", ["text"] = "14% von Grundmana\nSofort\nErfüllt den Paladin mit Heiliger Macht, durch den Angriffe auf Einzelziele den Effekt 'Tadel' auslösen, der im Verlauf von 5 Min. [(0.01 * Zaubermacht + 0.0193 * Angriffskraft) * 5 */ 100] zusätzlichen Heiligschaden verursacht. 'Tadel' ist bis zu 0-mal stapelbar. Sobald 0 Stapel erreicht werden, verursacht jeder Angriff des Paladins zusätzlich 0% Waffenschaden als Heiligschaden. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein. Hält 5 Min. lang an.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Feind (1 + 0.223 * Zaubermacht + 0.142 * Angriffskraft) Heiligschaden zu, dieser Schaden wird für jeden Stapel von 'Tadel' auf dem Ziel um 10% erhöht." }
entries[79973] = { ["name"] = "Wirbelwind", ["text"] = "Kanalisiert (Wirken in 5 sek.)\nFügt Gegnern vor dem Zaubernden alle 1 Sek. 34 Schaden zu." }
entries[79974] = { ["name"] = "Wirbelwind", ["text"] = "Sofort\nFügt Gegnern vor dem Zaubernden alle 1 Sek. 34 Schaden zu." }
entries[79975] = { ["name"] = "Gedankenkontrolle von Zul'Gurub", ["text"] = "Unbegrenzte Reichweite\nSofort\nErlaubt es Euch, das gefangene Schmetterschwanzjunge zu kontrollieren." }
entries[79976] = { ["name"] = "Aura der Vergeltung", ["text"] = "Sofort\nFügt jeder Kreatur, die den Zaubernden trifft, Heiligschaden zu." }
entries[79977] = { ["name"] = "Segen der Macht", ["text"] = "30 Meter Reichweite\nSofort\nBelegt ein verbündetes Ziel mit einem Segen, der 5 Min. lang seine Angriffskraft um 10%, seine Distanzangriffskraft um 10% erhöht und alle 5 Sek. 1% Mana regeneriert." }
entries[79983] = { ["name"] = "Summon Earthguard Elemental" }
entries[80003] = { ["name"] = "Schwarzer Pfeil", ["text"] = "35 Meter Reichweite\nBenötigt Distanzwaffe\nFeuert einen schwarzen Pfeil auf das Ziel ab, der Euren verursachten Schaden gegen das Ziel um 6% erhöht und 15 Sek. lang Schattenschaden verursacht." }
entries[80004] = { ["name"] = "Schlangenfalle", ["text"] = "Sofort\nEine Falle platzieren, die mehrere giftige Schlangen frei lässt, um den ersten Gegner anzugreifen, der sich nähert. Die Schlangen sterben nach 5 Sek. Die Falle besteht 1 Min. lang." }
entries[80005] = { ["name"] = "Sentinel Hill Skybox" }
entries[80007] = { ["name"] = "Schlangenfalle" }
entries[80008] = { ["name"] = "Summon Earthguard Elementalist (Reporting)" }
entries[80009] = { ["name"] = "Schlangengift", ["text"] = "40 Meter Reichweite\nWirken in 1 sek.\nBenötigt Distanzwaffe\nBeißt das Ziel und verursacht 15 Sek. lang alle 3 Sek. 6 Naturschaden." }
entries[80010] = { ["name"] = "Taxi Path Flavor" }
entries[80011] = { ["name"] = "Giftgetränkt", ["text"] = "Unbegrenzte Reichweite\nSofort\nGiftgetränkt zu sein verursacht alle 2 Sek. 962 Naturschaden und lässt Zauber und Fähigkeiten dem Ziel 1137 Naturschaden zufügen.\n(500ms Abklingzeit)" }
entries[80012] = { ["name"] = "Schimärenschuss", ["text"] = "35 Meter Reichweite\n10 sek. Abklingzeit\nBenötigt Distanzwaffe\nVerursacht 125% Waffenschaden, frischt die Dauer Eures auf das Ziel wirkenden Gifts auf und löst einen Effekt aus:\n\nSchlangengift - Verursacht sofort 40% des von Eurer Fähigkeit 'Schlangengift' verursachten Schadens.\n\nVipernbiss - Stellt für Euch sofort Mana in Höhe von 60% des von Eurer Fähigkeit 'Vipernbiss' entzogenen Manas her.\n\nSkorpidgift - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nicht öfter als ein Mal pro Minute auftreten." }
entries[80013] = { ["name"] = "Schimärenschuss - Schlange", ["text"] = "100 Meter Reichweite\nVerursacht 0% Waffenschaden, frischt die Dauer Eures auf das Ziel wirkenden Gifts auf und löst einen Effekt aus:\n\nSchlangengift - Verursacht sofort 40% des von Eurer Fähigkeit 'Schlangengift' verursachten Schadens.\n\nVipernbiss - Stellt für Euch sofort Mana in Höhe von 60% des von Eurer Fähigkeit 'Vipernbiss' entzogenen Manas her.\n\nSkorpidgift - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nicht öfter als ein Mal pro Minute auftreten." }
entries[80014] = { ["name"] = "Gift auslöschen", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt dem Ziel Eurer Zauber und Fähigkeiten 1137 Naturschaden zu." }
entries[80015] = { ["name"] = "Zuverlässiger Schuss", ["text"] = "35 Meter Reichweite\nWirken in 1.5 sek.\nBenötigt Distanzwaffe\nEin zuverlässiger Schuss, der 100% Waffenschaden als körperlichen Schaden verursacht." }
